#!/usr/bin/env python3
"""Probe which PDF-related Python modules are available."""
import importlib

mods = [
    "pypdf", "PyPDF2", "pdfplumber", "reportlab", "fitz", "pypdfium2",
    "pikepdf", "pdfrw", "os", "datetime",
]
for m in mods:
    try:
        mod = importlib.import_module(m)
        print(f"OK      {m}  ({getattr(mod, '__version__', 'unknown')})")
    except Exception as e:
        print(f"MISSING {m}: {type(e).__name__}: {e}")

