#!/usr/bin/env python3
"""Check for node.js and pdf-lib availability, and any local pip cache/wheels."""
import importlib.util
import os
import shutil
import subprocess

print("node:", shutil.which("node"))
print("npm:", shutil.which("npm"))
print("npx:", shutil.which("npx"))

# Check pip cache dir for wheels
pip_cache = os.path.expanduser("~/.cache/pip")
if os.path.isdir(pip_cache):
    wheels = []
    for root, _dirs, files in os.walk(pip_cache):
        for f in files:
            if f.endswith(".whl") and any(k in f.lower() for k in ("pypdf", "reportlab", "pdf", "pil", "pillow")):
                wheels.append(os.path.join(root, f))
    print("pip cache wheels:", wheels[:20] if wheels else "none matching")

# Look for wheels in common local dirs
for base in ["/tmp", os.getcwd(), os.path.expanduser("~/.wheels"), os.path.expanduser("~/wheels")]:
    if not os.path.isdir(base):
        continue
    try:
        hits = []
        for root, _dirs, files in os.walk(base):
            # keep it shallow
            depth = root[len(base):].count(os.sep)
            if depth > 3:
                continue
            for f in files:
                if f.endswith(".whl"):
                    hits.append(os.path.join(root, f))
        if hits:
            print(f"{base}: {hits[:20]}")
    except Exception as e:
        print(f"{base}: error {e}")

